1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.function.Predicate;
4	
5	/**
6	 * The single definition of an owner's customer code: {@code <REGION>-<HASH8>}, where REGION
7	 * is the region derived from the owner's postcode (see {@link Locality}) and HASH8 is the
8	 * first 8 upper-case hex characters of SHA-256 over the owner's normalized telephone
9	 * followed by its last name. The code carries no sequence number and so is stable for a
10	 * given identity.
11	 *
12	 * <p>Formatting only; the region and identity fields are supplied by the caller
13	 * ({@link AssignOwnerCustomerCode} derives the region and reads the stored fields).
14	 */
15	public final class CustomerCode {
16	
17	    private static final int HASH_LENGTH = 8;
18	
19	    private CustomerCode() {
20	    }
21	
22	    /**
23	     * Format {@code region} and the identity fields into a customer code, e.g.
24	     * {@code format("NSW", "+61412345678", "Smithers")} yields {@code "NSW-1A2B3C4D"} (the
25	     * hash segment being the first 8 upper-case hex digits of SHA-256 over
26	     * {@code telephone + lastName}).
27	     */
28	    public static String format(String region, String telephone, String lastName) {
29	        return region + "-" + hash8(telephone, lastName);
30	    }
31	
32	    /**
33	     * De-duplicate {@code code} against codes already in use. If {@code code} is free it is
34	     * returned unchanged; otherwise {@code -<n>} is appended with the smallest {@code n >= 2}
35	     * that yields an unused code, e.g. a third collision on {@code "NSW-1A2B3C4D"} becomes
36	     * {@code "NSW-1A2B3C4D-3"}. The suffix leaves {@link #region(String)} unchanged.
37	     *
38	     * @param code  the freshly formatted code
39	     * @param inUse tests whether a candidate code is already taken
40	     */
41	    public static String deduplicate(String code, Predicate<String> inUse) {
42	        if (!inUse.test(code)) {
43	            return code;
44	        }
45	        for (int n = 2; ; n++) {
46	            String candidate = code + "-" + n;
47	            if (!inUse.test(candidate)) {
48	                return candidate;
49	            }
50	        }
51	    }
52	
53	    /** The region segment of {@code customerCode} (the text before the first {@code '-'}), or
54	     *  {@code null} when the code is absent. */
55	    public static String region(String customerCode) {
56	        if (customerCode == null) {
57	            return null;
58	        }
59	        int dash = customerCode.indexOf('-');
60	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
61	    }
62	
63	    /** The first 8 upper-case hex characters of SHA-256 over {@code telephone + lastName}. */
64	    private static String hash8(String telephone, String lastName) {
65	        return Sha256.hex(telephone + lastName, HASH_LENGTH);
66	    }
67	}
