6	/**
7	 * Step of {@code POST /api/owners} run after {@link SaveOwner}, once the owner carries its id:
8	 * associates the request's {@code Idempotency-Key} (published by {@link RecallIdempotentOwner})
9	 * with that id, so a later repeat of the same key replays this owner instead of creating another.
10	 * A request without a key publishes {@code null} and records nothing.
11	 */
12	public class RecordIdempotentOwner {
13	
14	    public void service(@Val String idempotencyKey, @Val Owner owner, IdempotencyStore idempotencyStore) {
15	        idempotencyStore.record(idempotencyKey, owner.getId());
16	    }
17	}
